    /**
     * Preferred Language
     */
    preferred_language?: 'auto' | 'pt-PT' | 'en';
    /**
     * Retention Days
     *
     * Nulo = sem limite (até ao máximo do sistema)
     */
    retention_days?: 30 | 90 | 365 | null;
    /**
     * Save History
     *
     * Falso: conversas efémeras, apagadas ao fim de 24 h
     */
    save_history?: boolean;
    /**
     * Show Tool Steps
     */
    show_tool_steps?: boolean;
    /**
     * User Profile Enabled
     *
     * Perfil do utilizador (user) ligado
     */
    user_profile_enabled?: boolean;
    /**
     * Verbosity
     */
    verbosity?: 'short' | 'balanced' | 'detailed';
    /**
     * Web Search
     *
     * auto: o copiloto pesquisa na web só quando o assunto é externo ao Novelo; off: nunca (`/websearch off`)
     */
    web_search?: 'auto' | 'off';
    /**
     * Web Search Available
     *
     * O sistema oferece pesquisa na web a este utilizador (flag, região, papel)
     */
